CREATE OR REPLACE FUNCTION validate_employee_salary()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.salary <= 0 OR NEW.salary > 500000 THEN
        RAISE EXCEPTION 'Invalid salary: %. Must be between 0 and 500000', NEW.salary;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_validate_salary
BEFORE INSERT OR UPDATE ON employees
FOR EACH ROW EXECUTE FUNCTION validate_employee_salary();
